effect.shader:
mat2 rot(float a){
  float c = cos(a);
  float s = sin(a);
  return mat2(c, s, -s, c);
}

float fx(vec2 uv,float fadetime,float tt){
  float light = 0.05;
  float rip = 0.5+sin(length(uv)*rippleFreq+tt)*0.5;
  rip = 1.0+rip*rippleAmt;
  uv*=rip*0.5;
  uv *= rot(tt*rotSpeed);

  float vv2 = smoothstep(0.0,0.45,fadetime);
  float vv = mix(fadeMin,fadeMax,fadetime);

  float tth = tt*0.5;
  for (int i=0;i<12;i++){
    float x = 1.5 + 2.0*float(i);
    uv *= rot(x*4.0+length(uv)*0.126*sin(tth*0.05));
    vec2 f = vec2(cos(cos(tth*0.6+x + uv.x * x) - uv.y * dot(vec2(x + uv.y), vec2(sin(x), cos(x)))));
    light += (vv / distance(uv, f)) - (0.01 * distance(vec2((cos(tth*0.3 + uv.y))), vec2(uv)));
    light-=x*0.001 + 0.001;
  }

  light = clamp(light,0.0,1.0);
  return light*vv2;
}

void main(){
  vec2 res = acScreenSize;
  vec2 uv = acScreenNorm;
  vec4 a = texture2DCv(inputA.texture, uv);
  vec4 bTex = texture2DCv(inputB.texture, uv);
  vec3 bCol = (int(useSecondTexture)==1) ? bTex.rgb : altColor.rgb;

  float tt = phase * timeScale;
  vec2 uvC = (uv*res - 0.5*res)/max(res.y,1.0);
  float fadetime = 0.5+sin(tt*fadeSpeed)*0.5;
  float fade = fx(uvC,fadetime,tt);

  vec3 outRGB = mix(a.rgb, bCol, fade);
  float aOut = a.a * opacity;
  gl_FragColor = vec4(outRGB, 1.0) * aOut;
}
